package com.cvp.maintenance.adapter.inbound.kafka;
import com.cvp.maintenance.application.AppointmentLifecycleService; import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.stereotype.Component;
@Component public class AppointmentLifecycleListener {private final AppointmentLifecycleService service;private final ObjectMapper mapper;public AppointmentLifecycleListener(AppointmentLifecycleService s,ObjectMapper m){service=s;mapper=m;}@KafkaListener(topics="${maintenance-reminder.integration.appointment.booked-topic}")public void booked(String p)throws Exception{service.booked(mapper.readValue(p,AppointmentLifecycleService.Event.class));}@KafkaListener(topics="${maintenance-reminder.integration.appointment.completed-topic}")public void completed(String p)throws Exception{service.completed(mapper.readValue(p,AppointmentLifecycleService.Event.class));}}
